SELECT jsonb_build_object('customer',(SELECT count(*) FROM app.customer_profiles WHERE id='91a2eaf4-43e8-5dc7-8eb4-59a62c12d965'),'command',(SELECT count(*) FROM platform.runtime_command_receipt WHERE id IN ('76d917ea-8d8b-51a1-a1b4-c4b9083c4657','395c4507-3f19-55fa-a458-f9b3ffb8d0fc')), 'history',(SELECT count(*) FROM app.customer_profile_lifecycle_event WHERE customer_profile_id='91a2eaf4-43e8-5dc7-8eb4-59a62c12d965'),'evidence',(SELECT count(*) FROM platform.owner_mutation_evidence WHERE aggregate_kind='CustomerProfile' AND aggregate_id='91a2eaf4-43e8-5dc7-8eb4-59a62c12d965'),'outbox',(SELECT count(*) FROM platform.runtime_outbox_message WHERE command_receipt_id IN ('76d917ea-8d8b-51a1-a1b4-c4b9083c4657','395c4507-3f19-55fa-a458-f9b3ffb8d0fc')),'track_enrollments',(SELECT count(*) FROM app.track_enrollment_receipt WHERE profile_id='91a2eaf4-43e8-5dc7-8eb4-59a62c12d965'),'coherent',EXISTS(SELECT 1 FROM app.customer_profiles c
 JOIN platform.runtime_command_receipt q ON q.id='76d917ea-8d8b-51a1-a1b4-c4b9083c4657' AND q.owner_module_id='customer_buyer_profile' AND q.operation='SH-004.v1'
  AND q.subject_scope='CustomerProfile:'||c.id::text AND q.semantic_key='customer-controls-customer-09-missing-result-receipt' AND q.fingerprint='a210f8953cbea6b780e4f80512e8037fcc648a1b8c18cb584e9d8323b3265fae'
  AND q.state='committed' AND q.source_revision=0 AND q.result_schema_id='SH-004.v1#/$defs/response' AND q.result_schema_version='1'
  AND q.result_body='{"contract":"SH-004.v1","requestId":"customer-09-missing-result-receipt","status":"ok","value":{"customerProfileId":"91a2eaf4-43e8-5dc7-8eb4-59a62c12d965","userId":"0af602c5-c39a-55af-bda5-bc442ceb79d1","lifecycle":"active","sourceToken":"0"}}'::jsonb AND q.result_digest=encode(sha256(convert_to(q.result_body::text,'UTF8')),'hex')
 JOIN app.customer_profile_lifecycle_event h ON h.id='47393935-7f69-5220-b56d-6b474f1eb3b8' AND h.customer_profile_id=c.id AND h.command_receipt_id=q.id
  AND h.source_revision=0 AND h.from_status IS NULL AND h.to_status=c.status AND h.actor_user_id=c.user_id AND h.name='customer.lifecycle_changed.v1'
 JOIN platform.owner_mutation_evidence e ON e.id='a65a7f21-b689-5d2c-a50d-93ad04a64d28' AND e.command_receipt_id=q.id AND e.owner_module_id=q.owner_module_id
  AND e.aggregate_kind='CustomerProfile' AND e.aggregate_id=c.id::text AND e.previous_revision IS NULL AND e.committed_revision=0
  AND e.action=q.operation AND e.decision_ref='customer-controls-v1' AND e.evidence_schema_version='1'
  AND e.evidence_schema_id='urn:workinants:database-review:owner-evidence:v1#/$defs/CustomerProfile'
  AND e.evidence_body='{"schema":"database-owner-evidence.v1","owner":"customer_buyer_profile","model":"CustomerProfile","primaryKey":{"id":"91a2eaf4-43e8-5dc7-8eb4-59a62c12d965"},"prior":null,"committed":{"id":"91a2eaf4-43e8-5dc7-8eb4-59a62c12d965","userId":"0af602c5-c39a-55af-bda5-bc442ceb79d1","status":"active","revision":"0","privacyGeneration":"0"},"decisionRef":"customer-controls-v1"}'::jsonb AND e.evidence_digest=encode(sha256(convert_to(e.evidence_body::text,'UTF8')),'hex')
 WHERE c.id='91a2eaf4-43e8-5dc7-8eb4-59a62c12d965' AND c.user_id='0af602c5-c39a-55af-bda5-bc442ceb79d1' AND c.status='active' AND c.revision=0 AND c.privacy_generation=0
  AND c.display_name IS NULL AND c.avatar_media_id IS NULL AND c.city IS NULL AND c.state IS NULL AND c.country IS NULL AND c.archived_at IS NULL
  AND q.mutation_transaction_id=c.mutation_transaction_id AND h.mutation_transaction_id=c.mutation_transaction_id AND e.mutation_transaction_id=c.mutation_transaction_id
  AND (SELECT count(*) FROM platform.runtime_outbox_message o WHERE o.command_receipt_id=q.id AND o.producer_owner=q.owner_module_id
   AND o.aggregate_kind='CustomerProfile' AND o.aggregate_id=c.id::text AND o.source_revision=0 AND o.source_generation=0 AND o.schema_version='1'
   AND o.causation_id=q.id::text AND o.correlation_id='customer-09-missing-result-receipt' AND o.mutation_transaction_id=c.mutation_transaction_id
   AND o.payload_hash=encode(sha256(convert_to(o.payload::text,'UTF8')),'hex')
   AND ((o.id='4d2294c3-3a82-5ba6-bf0f-d3a6b532c10a' AND o.ordinal=0 AND o.kind='event' AND o.name='customer.lifecycle_changed.v1'
    AND o.payload_schema_id='urn:workin-ants:types:v1#/$defs/EventPayload_customer_lifecycle_changed_v1' AND o.payload='{"eventName":"customer.lifecycle_changed.v1","customerProfileId":"91a2eaf4-43e8-5dc7-8eb4-59a62c12d965","userId":"0af602c5-c39a-55af-bda5-bc442ceb79d1","lifecycleRevision":"0","safeState":"active"}'::jsonb)
    OR (o.id='bece2095-817d-51ce-b4a7-7479c088eabc' AND o.ordinal=1 AND o.kind='command' AND o.name='assignDefaultFreeTrack.v1'
    AND o.payload_schema_id='urn:workinants:database-review:foundation-payloads:v1#/$defs/assignDefaultFreeTrackCustomerCommand' AND o.payload='{"sourceOwner":"customer_buyer_profile","userId":"0af602c5-c39a-55af-bda5-bc442ceb79d1","track":"customer","customerProfileId":"91a2eaf4-43e8-5dc7-8eb4-59a62c12d965","sourceCreationRevision":"0","sourceCreationReceipt":"76d917ea-8d8b-51a1-a1b4-c4b9083c4657","semanticKey":"customer_buyer_profile/91a2eaf4-43e8-5dc7-8eb4-59a62c12d965/default-free-enrollment/v1"}'::jsonb)))=2));
